import React, { useState } from "react";
import TeacherView from "./components/TeacherView";
import StudentView from "./components/StudentView";

export default function App() {
  const [role, setRole] = useState(null);

  if (!role) {
    return (
      <div className="app-select-role">
        <h1>Live Polling System</h1>
        <div className="role-buttons">
          <button onClick={() => setRole("teacher")}>I am a Teacher</button>
          <button onClick={() => setRole("student")}>I am a Student</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <header className="app-header">
        <button onClick={() => setRole(null)}>← Back</button>
        <h2>{role === "teacher" ? "Teacher Panel" : "Student Panel"}</h2>
      </header>
      {role === "teacher" ? <TeacherView /> : <StudentView />}
    </div>
  );
}
